335	    /**
336	     * 결제 환불 처리 (필요한 경우)
337	     *
338	     * @param payment 환불할 결제 정보
339	     * @throws PaymentException 환불 처리 실패 시
340	     */
341	    private void handleRefundIfNecessary(Payment payment) {
342	        Instant start = Instant.now();
343	        try {
344	            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
345	                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
346	                return;
347	            }
348	
349	            log.info("결제 환불 처리 시작: 결제ID={}, impUid={}", payment.getId(), payment.getImpUid());
350	
351	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
352	
353	            if (refundSuccess) {
354	                payment.updateStatus(PaymentStatus.REFUNDED);
355	                paymentRepository.save(payment);
356	                log.info("결제 환불 처리 완료: 결제ID={}, 상태=REFUNDED", payment.getId());
357	            } else {
358	                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
359	                throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
360	                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
361	            }
362	
363	            // 처리 시간 로깅
364	            Instant end = Instant.now();
365	            Duration duration = Duration.between(start, end);
366	            log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
367	        } catch (PaymentException e) {
368	            throw e; // 이미 PaymentException이면 그대로 전파
369	        } catch (Exception e) {
370	            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
371	                    payment.getId(), e.getMessage(), e);
372	            throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
373	                    "환불 처리 중 오류가 발생했습니다: " + e.getMessage());
374	        }
375	    }
