428	    /**
429	     * 알림 전송
430	     *
431	     * @param order 주문 정보
432	     * @param sale  판매 정보
433	     */
434	    private void sendNotifications(Order order, Sale sale) {
435	        try {
436	            User buyer = order.getUser();
437	            if (buyer != null) {
438	                notificationCommandService.createNotification(
439	                        buyer.getId(),
440	                        NotificationCategory.SHOPPING,
441	                        NotificationType.BID,
442	                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
443	                );
444	                log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
445	            }
446	
447	            User seller = sale.getSeller();
448	            if (seller != null) {
449	                notificationCommandService.createNotification(
450	                        seller.getId(),
451	                        NotificationCategory.SHOPPING,
452	                        NotificationType.BID,
453	                        "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
454	                );
455	                log.debug("판매자 알림 전송 완료: 판매자ID={}", seller.getId());
